#!/usr/bin/env bash
###
# install-tf2-scout-sounds.sh
# Self-contained installer for TF2 Scout sound effects for Claude Code hooks.
# All 15 .wav files are embedded (base64) — no external downloads needed.
#
# Events:
#   SessionStart      → Battle cry / cheer sounds
#   UserPromptSubmit  → Positive vocalizations / good job / yes / thanks
#   Stop              → Special completed / domination / laugh sounds
#   Notification      → Jeers (permission prompts only)
#
# Prerequisites:
#   - macOS (uses afplay + base64 -D)
#
# Usage: bash install-tf2-scout-sounds.sh
###
set -euo pipefail

SOUNDS_DIR="$HOME/.claude/hooks/sounds/tf2_scout"
mkdir -p "$SOUNDS_DIR"

echo "Extracting 15 TF2 Scout sound files..."

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_battlecry01.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_battlecry03.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_cheers02.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_domination02.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_domination15.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_goodjob02.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_jeers02.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_laughlong01.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_laughlong02.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_positivevocalization01.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_positivevocalization02.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_specialcompleted02.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_specialcompleted03.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_thanks01.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Scout_yes01.wav"

B64EOF

echo ""
echo "Done! TF2 Scout sounds installed to $SOUNDS_DIR"
echo "To test: afplay $SOUNDS_DIR/Scout_battlecry01.wav"
